const body = $json.body ?? $json;

const name = String(body.name ?? '').trim();
const email = String(body.email ?? '').trim();
const message = String(body.message ?? '').trim();
const budget = Number(body.budget ?? 0);

if (!name || !email || !message) {
  throw new Error('Missing required fields: name, email, message');
}

const urgent = /urgent|asap|today|tomorrow|24\s*hours?/i.test(message);
const highValue = Number.isFinite(budget) && budget >= 250;

let priority = 'normal';
if (urgent && highValue) priority = 'high';
else if (urgent || highValue) priority = 'medium';

return [{
  json: {
    ok: true,
    lead: { name, email, message, budget },
    triage: {
      priority,
      urgent,
      highValue,
      nextAction: priority === 'high'
        ? 'reply_now'
        : priority === 'medium'
          ? 'review_today'
          : 'queue'
    }
  }
}];
